{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}
// Fold ASCII letters only: non-ASCII characters remain significant.
function foldAscii(value) {
  return value.replace(/[A-Z]/g, (letter) => letter.toLowerCase());
}

export function normalizeSearchQuery(query) {
  return foldAscii(query.trim());
}

// Apply normalization on submission; matching consumes that applied query.
export function matchesSearch(value, query) {
  return foldAscii(value).includes(query);
}

export function filterProjects(projects, archiveFilter, query = '') {
  return projects.filter((project) => project.archived === (archiveFilter === 'archived')
    && matchesSearch(project.name, query));
}
import test from 'node:test';
import assert from 'node:assert/strict';
import { filterProjects, matchesSearch, normalizeSearchQuery } from '../public/search.js';
import { filterTasks } from '../public/task-filters.js';

test('search trims edges, folds only ASCII letters, and preserves internal whitespace', () => {
  for (const [value, input, expected] of [
    ['Build Workboard', ' \tWORK\n ', true],
    ['Build Workboard', 'board', true],
    ['Build Workboard', 'build  work', false],
    ['Build  Workboard', 'BUILD  WORK', true],
    ['Build\tWorkboard', 'build work', false],
    ['Ä Team', 'ä team', false],
    ['Ä Team', 'Ä TEAM', true],
    ['Anything', ' \t\n ', true],
    ['<script> & [team]', '[TEAM]', true],
    ['Anything', 'missing', false],
  ]) {
    assert.equal(matchesSearch(value, normalizeSearchQuery(input)), expected);
  }
});

test('project search intersects archive state and retains order, summaries, and data', () => {
  const projects = [
    { id: 1, name: 'Team Alpha', archived: false, completed_count: 2, total_count: 3 },
    { id: 2, name: 'Other', archived: false, completed_count: 0, total_count: 0 },
    { id: 3, name: 'TEAM Archive', archived: true, completed_count: 1, total_count: 1 },
    { id: 4, name: 'Team Beta', archived: false, completed_count: 0, total_count: 2 },
  ];
  const original = structuredClone(projects);
  const query = normalizeSearchQuery(' TEAM ');
  const ids = (archive, search = query) => filterProjects(projects, archive, search).map((project) => project.id);
  assert.deepEqual(ids('active'), [1, 4]);
  assert.deepEqual(ids('archived'), [3]);
  assert.deepEqual(ids('active', ''), [1, 2, 4]);
  assert.deepEqual(projects, original);
  projects[0].archived = true;
  assert.deepEqual(ids('active'), [4]);
  assert.deepEqual(ids('archived'), [1, 3]);
  projects[0].archived = false;
  projects[0].name = 'Renamed';
  assert.deepEqual(ids('active'), [4]);
});

test('task search intersects all filters and re-evaluates edits without changing saved data', () => {
  const tasks = [
    { id: 8, title: 'Ship ALPHA', completed: false, priority: 'High', due_date: '2026-01-01' },
    { id: 2, title: 'Ship beta', completed: false, priority: 'High', due_date: '2026-01-01' },
    { id: 5, title: 'Alpha done', completed: true, priority: 'High', due_date: '2026-01-01' },
    { id: 4, title: 'Alpha low', completed: false, priority: 'Low', due_date: '2026-01-01' },
    { id: 3, title: 'Alpha undated', completed: false, priority: 'High', due_date: '' },
    { id: 9, title: 'Alpha later', completed: false, priority: 'High', due_date: '2026-01-02' },
  ];
  const original = structuredClone(tasks);
  const query = normalizeSearchQuery(' ALPHA ');
  const range = { from: '2026-01-01', through: '2026-01-01' };
  for (const completion of ['all', 'open', 'completed']) {
    for (const priority of ['all', 'Low', 'Normal', 'High']) {
      for (const dueRange of [range, { from: '', through: '' }]) {
        const expected = filterTasks(tasks, completion, priority, dueRange).filter((task) => task.id !== 2);
        assert.deepEqual(filterTasks(tasks, completion, priority, dueRange, query), expected);
      }
    }
  }
  assert.deepEqual(filterTasks(tasks, 'all', 'all', undefined, query).map((task) => task.id), [8, 5, 4, 3, 9]);
  assert.deepEqual(tasks, original);
  const visible = () => filterTasks(tasks, 'open', 'High', range, query).map((task) => task.id);
  assert.deepEqual(visible(), [8]);
  tasks[0].title = 'No longer matches';
  assert.deepEqual(visible(), []);
  tasks[1].title = 'New Alpha match';
  assert.deepEqual(visible(), [2]);
  tasks[1].completed = true;
  assert.deepEqual(visible(), []);
  tasks[1].completed = false;
  tasks[1].priority = 'Low';
  assert.deepEqual(visible(), []);
  tasks[1].priority = 'High';
  tasks[1].due_date = '';
  assert.deepEqual(visible(), []);
  tasks[1].due_date = range.from;
  assert.deepEqual(visible(), [2]);
  tasks.splice(1, 1); // Moving removes the task from the source's search results.
  assert.deepEqual(visible(), []);
  tasks.push({ id: 10, title: 'Created alpha', completed: false, priority: 'High', due_date: range.from });
  assert.deepEqual(visible(), [10]);
  assert.deepEqual(range, { from: '2026-01-01', through: '2026-01-01' });
  assert.equal(query, 'alpha');
});
# Workboard

Requires Node.js 22.22.1. No package installation is needed.

```sh
npm start
```

The server binds to `0.0.0.0` on `PORT` (default `8080`). Set `DB_PATH` to the SQLite file to use (default `./data/workboard.sqlite`). Its parent directory is created automatically. Keep this file across server restarts to preserve projects, tasks, completion state, priorities, due dates, project defaults, and archive state. Existing databases are migrated automatically.

```sh
PORT=8080 DB_PATH=./data/workboard.sqlite npm start
npm test
```

`GET /health` returns `{"status":"ok"}`. The browser provides project creation at `/` and individual project pages at `/projects/<id>`.

Project pages support task creation, saved completion checkboxes, and All/Open/Completed filters. Tasks belong only to their project; filters default to All on each page load.

The Priority filter offers All, Low, Normal, and High. Tasks must match both filters and stay in creation order. Each filter keeps its selection when the other changes or a task is edited. Completion and priority edits immediately update matching rows. Both filters work in archived projects; filtering never changes saved data or completion summaries.

The project list defaults to Active and can show Archived projects. Archive and restore preserve all tasks. Archived project pages allow viewing and filtering tasks while task creation and completion controls are disabled; the server also rejects these changes. Each project row shows completed/total counts across all its tasks.

Active project pages allow renaming with a trimmed, nonempty name. Names persist without changing project URLs, list order, tasks, or summaries. Archived projects cannot be renamed until restored; both the browser controls and server enforce this restriction.

Each task row allows renaming with a trimmed, nonempty title. Renaming preserves ownership, creation order, completion state, filter membership, and project summaries. The completion checkbox label follows the saved title. Archived projects disable task rename controls and reject title updates until restored. Task titles persist across reloads and server restarts.

Each task has a saved Low, Normal, or High priority, defaulting to Normal for existing tasks. New tasks inherit their project’s saved default priority. Priority changes preserve the task's other fields and project summary; renaming preserves priority. Archived projects disable priority controls and reject updates until restored. Priorities persist across reloads and server restarts.

Each project page provides Default task priority with Low, Normal, and High options. Existing and new projects start at Normal. Changing the saved default affects only subsequently created tasks in that project and leaves both task filters unchanged. Archived projects show the saved default in a disabled control and reject updates until restored. Defaults survive renaming, reloads, and server restarts.

Each task row provides Task due date and Save due date. Empty input clears the date; otherwise a trimmed real Gregorian date in YYYY-MM-DD format (years 0001–9999) is required. Invalid dates leave saved data unchanged. Dates persist as calendar days without timezone conversion, independently for each task. Date changes preserve both filters and other task fields. Archived projects disable date controls and reject date updates until restored.

Due from, Due through, and Apply due range filter tasks by inclusive calendar-day boundaries alongside the completion and priority filters. A blank boundary is unbounded; both blank includes undated tasks, while any boundary excludes them. Invalid dates or a reversed range show an alert and preserve the previous applied range. Task edits immediately update matching rows without resetting filters; filters never alter saved data or summaries. Range controls remain usable in archived projects and reset to empty when reopening a project.

Each task row provides Destination project and Move task. Destinations are other active projects in project creation order, displayed by their current names. Moving keeps the source page and its filters open, removes the task from the source, and restores its remembered destination position on return. First-time arrivals and newly created tasks append after all positions established in that project, including positions of tasks currently elsewhere. Task identity, title, completion, priority, and due date remain unchanged; the destination's default applies only to new tasks. Both project summaries reflect their current tasks. Archived projects cannot send or receive tasks, and move controls are disabled when archived or when there are no eligible destinations. Moves and ordering persist across restarts; legacy databases retain their previous task order during migration.

Project search and Search projects apply a substring query alongside the Active/Archived filter. Task search and Search tasks intersect completion, priority, and the applied due range. Queries trim surrounding whitespace and ignore ASCII letter case while preserving internal whitespace and non-ASCII case. Search affects visibility only, preserving saved data, summaries, and order. Edits immediately re-evaluate the applied query without resetting other filters; archived pages still allow searching. Each page opening starts with an empty query, including returning through Projects.

import { filterTasks, normalizeDueRange } from './task-filters.js';
import { filterProjects, normalizeSearchQuery } from './search.js';

const app = document.querySelector('#app');

async function request(path, options) {
  const response = await fetch(path, options);
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || 'Unable to complete request');
  return body;
}

function showError(container, message) {
  container.textContent = message;
  container.hidden = false;
}

function renderRename(project) {
  const section = document.createElement('section');
  section.setAttribute('aria-label', 'Rename project');
  section.innerHTML = `
    <form>
      <label for="new-project-name">New project name</label>
      <div class="create-controls">
        <input id="new-project-name" type="text" autocomplete="off">
        <button type="submit">Rename project</button>
      </div>
    </form>
    <p role="alert" hidden></p>
  `;
  const form = section.querySelector('form');
  const input = form.querySelector('input');
  const button = form.querySelector('button');
  const alert = section.querySelector('[role="alert"]');
  input.value = project.name;
  input.disabled = project.archived;
  button.disabled = project.archived;
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (project.archived) return;
    alert.hidden = true;
    if (!input.value.trim()) {
      showError(alert, 'Project name is required');
      return;
    }
    button.disabled = true;
    try {
      Object.assign(project, await request(`/api/projects/${project.id}/name`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: input.value }),
      }));
      app.querySelector('h1').textContent = project.name;
      document.title = `${project.name} — Workboard`;
      input.value = project.name;
    } catch (error) {
      showError(alert, error.message);
    } finally {
      button.disabled = project.archived;
    }
  });
  app.append(section);
}

async function renderTasks(project) {
  const section = document.createElement('section');
  section.setAttribute('aria-label', 'Tasks');
  section.innerHTML = `
    <div class="task-filter">
      <label for="default-task-priority">Default task priority</label>
      <select id="default-task-priority">
        <option value="Low">Low</option>
        <option value="Normal">Normal</option>
        <option value="High">High</option>
      </select>
    </div>
    <form>
      <label for="task-title">Task title</label>
      <div class="create-controls">
        <input id="task-title" type="text" autocomplete="off">
        <button type="submit" disabled>Create task</button>
      </div>
    </form>
    <p role="alert" hidden></p>
    <div class="task-filter">
      <label for="task-filter">Task filter</label>
      <select id="task-filter">
        <option value="all">All</option>
        <option value="open">Open</option>
        <option value="completed">Completed</option>
      </select>
    </div>
    <div class="task-filter">
      <label for="priority-filter">Priority filter</label>
      <select id="priority-filter">
        <option value="all">All</option>
        <option value="Low">Low</option>
        <option value="Normal">Normal</option>
        <option value="High">High</option>
      </select>
    </div>
    <form id="due-range">
      <label for="due-from">Due from</label>
      <input id="due-from" type="text" placeholder="YYYY-MM-DD" autocomplete="off">
      <label for="due-through">Due through</label>
      <div class="create-controls">
        <input id="due-through" type="text" placeholder="YYYY-MM-DD" autocomplete="off">
        <button type="submit">Apply due range</button>
      </div>
    </form>
    <form id="task-search-form" class="search-form">
      <label for="task-search">Task search</label>
      <div class="create-controls">
        <input id="task-search" type="text" autocomplete="off">
        <button type="submit">Search tasks</button>
      </div>
    </form>
    <div id="tasks"></div>
  `;
  app.append(section);
  const form = section.querySelector('form');
  const input = section.querySelector('input');
  const button = form.querySelector('button');
  const alert = section.querySelector('[role="alert"]');
  const filter = section.querySelector('#task-filter');
  const priorityFilter = section.querySelector('#priority-filter');
  const dueRangeForm = section.querySelector('#due-range');
  const dueFrom = section.querySelector('#due-from');
  const dueThrough = section.querySelector('#due-through');
  // Draft inputs only replace the applied range after successful validation.
  let dueRange = { from: '', through: '' };
  const searchForm = section.querySelector('#task-search-form');
  const searchInput = section.querySelector('#task-search');
  let searchQuery = '';
  const defaultPriority = section.querySelector('#default-task-priority');
  defaultPriority.value = project.default_task_priority;
  defaultPriority.disabled = project.archived;
  defaultPriority.addEventListener('change', async () => {
    defaultPriority.disabled = true;
    button.disabled = true;
    alert.hidden = true;
    try {
      Object.assign(project, await request(`/api/projects/${project.id}/default-task-priority`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ priority: defaultPriority.value }),
      }));
    } catch (error) {
      showError(alert, error.message);
    } finally {
      defaultPriority.value = project.default_task_priority;
      defaultPriority.disabled = project.archived;
      button.disabled = project.archived;
    }
  });
  const list = section.querySelector('#tasks');
  const endpoint = `/api/projects/${project.id}/tasks`;
  let tasks = [];
  let destinations = [];

  function displayTasks() {
    list.replaceChildren();
    for (const task of filterTasks(tasks, filter.value, priorityFilter.value, dueRange, searchQuery)) {
      const row = document.createElement('div');
      row.dataset.testid = 'task-row';
      row.className = 'task-row';
      const title = document.createElement('span');
      title.textContent = task.title;
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = task.completed;
      checkbox.disabled = project.archived;
      checkbox.setAttribute('aria-label', `Complete ${task.title}`);
      checkbox.addEventListener('change', async () => {
        checkbox.disabled = true;
        alert.hidden = true;
        try {
          const updated = await request(`${endpoint}/${task.id}`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: checkbox.checked }),
          });
          Object.assign(task, updated);
          displayTasks();
        } catch (error) {
          checkbox.checked = task.completed;
          showError(alert, error.message);
        } finally {
          checkbox.disabled = project.archived;
        }
      });
      const renameForm = document.createElement('form');
      renameForm.className = 'task-rename';
      const renameLabel = document.createElement('label');
      renameLabel.htmlFor = `new-task-title-${task.id}`;
      renameLabel.textContent = 'New task title';
      const renameInput = document.createElement('input');
      renameInput.id = renameLabel.htmlFor;
      renameInput.type = 'text';
      renameInput.autocomplete = 'off';
      renameInput.value = task.title;
      renameInput.disabled = project.archived;
      const renameButton = document.createElement('button');
      renameButton.type = 'submit';
      renameButton.textContent = 'Rename task';
      renameButton.disabled = project.archived;
      const renameControls = document.createElement('div');
      renameControls.className = 'create-controls';
      renameControls.append(renameInput, renameButton);
      renameForm.append(renameLabel, renameControls);
      renameForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (project.archived) return;
        alert.hidden = true;
        if (!renameInput.value.trim()) {
          showError(alert, 'Task title is required');
          return;
        }
        renameButton.disabled = true;
        try {
          const updated = await request(`${endpoint}/${task.id}/title`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ title: renameInput.value }),
          });
          task.title = updated.title;
          displayTasks();
        } catch (error) {
          showError(alert, error.message);
        } finally {
          renameButton.disabled = project.archived;
        }
      });
      const priorityControls = document.createElement('div');
      const priorityLabel = document.createElement('label');
      priorityLabel.htmlFor = `task-priority-${task.id}`;
      priorityLabel.textContent = 'Task priority';
      const prioritySelect = document.createElement('select');
      prioritySelect.id = priorityLabel.htmlFor;
      for (const priority of ['Low', 'Normal', 'High']) {
        const option = document.createElement('option');
        option.value = priority;
        option.textContent = priority;
        prioritySelect.append(option);
      }
      prioritySelect.value = task.priority;
      prioritySelect.disabled = project.archived;
      prioritySelect.addEventListener('change', async () => {
        prioritySelect.disabled = true;
        alert.hidden = true;
        try {
          const updated = await request(`${endpoint}/${task.id}/priority`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ priority: prioritySelect.value }),
          });
          task.priority = updated.priority;
          displayTasks();
        } catch (error) {
          prioritySelect.value = task.priority;
          showError(alert, error.message);
        } finally {
          prioritySelect.disabled = project.archived;
        }
      });
      priorityControls.append(priorityLabel, prioritySelect);
      const dueDateForm = document.createElement('form');
      dueDateForm.className = 'task-due-date';
      const dueDateLabel = document.createElement('label');
      dueDateLabel.htmlFor = `task-due-date-${task.id}`;
      dueDateLabel.textContent = 'Task due date';
      const dueDateInput = document.createElement('input');
      dueDateInput.id = dueDateLabel.htmlFor;
      dueDateInput.type = 'text';
      dueDateInput.placeholder = 'YYYY-MM-DD';
      dueDateInput.value = task.due_date;
      dueDateInput.disabled = project.archived;
      const dueDateButton = document.createElement('button');
      dueDateButton.type = 'submit';
      dueDateButton.textContent = 'Save due date';
      dueDateButton.disabled = project.archived;
      const dueDateControls = document.createElement('div');
      dueDateControls.className = 'create-controls';
      dueDateControls.append(dueDateInput, dueDateButton);
      dueDateForm.append(dueDateLabel, dueDateControls);
      dueDateForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (project.archived) return;
        alert.hidden = true;
        dueDateButton.disabled = true;
        try {
          const updated = await request(`${endpoint}/${task.id}/due-date`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ due_date: dueDateInput.value }),
          });
          task.due_date = updated.due_date;
          displayTasks();
        } catch (error) {
          showError(alert, error.message);
        } finally {
          dueDateButton.disabled = project.archived;
        }
      });
      const moveForm = document.createElement('form');
      moveForm.className = 'task-move';
      const destinationLabel = document.createElement('label');
      destinationLabel.htmlFor = `destination-project-${task.id}`;
      destinationLabel.textContent = 'Destination project';
      const destinationSelect = document.createElement('select');
      destinationSelect.id = destinationLabel.htmlFor;
      for (const destination of destinations) {
        const option = document.createElement('option');
        option.value = String(destination.id);
        option.textContent = destination.name;
        destinationSelect.append(option);
      }
      const cannotMove = project.archived || destinations.length === 0;
      destinationSelect.disabled = cannotMove;
      const moveButton = document.createElement('button');
      moveButton.type = 'submit';
      moveButton.textContent = 'Move task';
      moveButton.disabled = cannotMove;
      const moveControls = document.createElement('div');
      moveControls.className = 'create-controls';
      moveControls.append(destinationSelect, moveButton);
      moveForm.append(destinationLabel, moveControls);
      moveForm.addEventListener('submit', async (event) => {
        event.preventDefault();
        if (cannotMove) return;
        alert.hidden = true;
        moveButton.disabled = true;
        destinationSelect.disabled = true;
        try {
          await request(`${endpoint}/${task.id}/move`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ destination_project_id: Number(destinationSelect.value) }),
          });
          tasks = tasks.filter((existing) => existing.id !== task.id);
          displayTasks();
        } catch (error) {
          showError(alert, error.message);
        } finally {
          moveButton.disabled = cannotMove;
          destinationSelect.disabled = cannotMove;
        }
      });
      row.append(title, checkbox, priorityControls, renameForm, dueDateForm, moveForm);
      list.append(row);
    }
  }

  filter.addEventListener('change', displayTasks);
  priorityFilter.addEventListener('change', displayTasks);
  searchForm.addEventListener('submit', (event) => {
    event.preventDefault();
    searchQuery = normalizeSearchQuery(searchInput.value);
    displayTasks();
  });
  dueRangeForm.addEventListener('submit', (event) => {
    event.preventDefault();
    alert.hidden = true;
    try {
      dueRange = normalizeDueRange(dueFrom.value, dueThrough.value);
      dueFrom.value = dueRange.from;
      dueThrough.value = dueRange.through;
      displayTasks();
    } catch (error) {
      showError(alert, error.message);
    }
  });
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    if (project.archived) return;
    alert.hidden = true;
    if (!input.value.trim()) {
      showError(alert, 'Task title is required');
      return;
    }
    button.disabled = true;
    try {
      tasks.push(await request(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: input.value }),
      }));
      displayTasks();
      input.value = '';
      input.focus();
    } catch (error) {
      showError(alert, error.message);
    } finally {
      button.disabled = project.archived;
    }
  });

  try {
    const [savedTasks, projects] = await Promise.all([request(endpoint), request('/api/projects')]);
    tasks = savedTasks;
    destinations = projects.filter((candidate) => !candidate.archived && candidate.id !== project.id);
    displayTasks();
    button.disabled = project.archived;
  } catch (error) {
    showError(alert, error.message);
  }
}

async function render() {
  const match = location.pathname.match(/^\/projects\/([1-9]\d*)$/);
  if (match) {
    app.innerHTML = '<button id="back" type="button">Projects</button><h1>Loading project…</h1><p role="alert" hidden></p>';
    document.querySelector('#back').addEventListener('click', () => location.assign('/'));
    try {
      const project = await request(`/api/projects/${match[1]}`);
      app.querySelector('h1').textContent = project.name;
      document.title = `${project.name} — Workboard`;
      if (project.archived) {
        const notice = document.createElement('p');
        notice.textContent = 'Archived project';
        app.append(notice);
      }
      renderRename(project);
      await renderTasks(project);
    } catch (error) {
      app.querySelector('h1').textContent = 'Project unavailable';
      showError(app.querySelector('[role="alert"]'), error.message);
    }
    return;
  }

  app.innerHTML = `
    <h1>Workboard</h1>
    <form>
      <label for="project-name">Project name</label>
      <div class="create-controls">
        <input id="project-name" name="name" type="text" autocomplete="off">
        <button type="submit">Create project</button>
      </div>
    </form>
    <p role="alert" hidden></p>
    <div class="project-filter">
      <label for="project-filter">Project filter</label>
      <select id="project-filter">
        <option value="active">Active</option>
        <option value="archived">Archived</option>
      </select>
    </div>
    <form id="project-search-form" class="search-form">
      <label for="project-search">Project search</label>
      <div class="create-controls">
        <input id="project-search" type="text" autocomplete="off">
        <button type="submit">Search projects</button>
      </div>
    </form>
    <section aria-label="Projects" id="projects"></section>
  `;
  const form = app.querySelector('form');
  const input = app.querySelector('input');
  const alert = app.querySelector('[role="alert"]');
  const list = app.querySelector('#projects');
  const filter = app.querySelector('select');
  const searchForm = app.querySelector('#project-search-form');
  const searchInput = app.querySelector('#project-search');
  let searchQuery = '';
  let projects = [];

  function displayProjects() {
    list.replaceChildren();
    filterProjects(projects, filter.value, searchQuery).forEach(appendProject);
  }

  filter.addEventListener('change', displayProjects);
  searchForm.addEventListener('submit', (event) => {
    event.preventDefault();
    searchQuery = normalizeSearchQuery(searchInput.value);
    displayProjects();
  });

  function appendProject(project) {
    const row = document.createElement('div');
    row.dataset.testid = 'project-row';
    row.className = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const summary = document.createElement('span');
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completed_count}/${project.total_count} completed`;
    const button = document.createElement('button');
    button.type = 'button';
    button.textContent = 'Open project';
    button.addEventListener('click', () => location.assign(`/projects/${project.id}`));
    const archiveButton = document.createElement('button');
    archiveButton.type = 'button';
    archiveButton.textContent = project.archived ? 'Restore project' : 'Archive project';
    archiveButton.addEventListener('click', async () => {
      archiveButton.disabled = true;
      alert.hidden = true;
      try {
        Object.assign(project, await request(`/api/projects/${project.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ archived: !project.archived }),
        }));
        displayProjects();
      } catch (error) {
        showError(alert, error.message);
      } finally {
        archiveButton.disabled = false;
      }
    });
    row.append(name, summary, button, archiveButton);
    list.append(row);
  }

  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.hidden = true;
    if (!input.value.trim()) {
      showError(alert, 'Project name is required');
      return;
    }
    const button = form.querySelector('button');
    button.disabled = true;
    try {
      const project = await request('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: input.value }),
      });
      projects.push(project);
      displayProjects();
      input.value = '';
      input.focus();
    } catch (error) {
      showError(alert, error.message);
    } finally {
      button.disabled = false;
    }
  });

  form.querySelector('button').disabled = true;
  try {
    projects = await request('/api/projects');
    displayProjects();
  } catch (error) {
    showError(alert, error.message);
  } finally {
    form.querySelector('button').disabled = false;
  }
}

